local MatchType = {
    FriendMatch          = 1, --- 好友匹配
    FriendMatchComplete  = 2, --- 好友匹配完成
    RalliesMatch         = 3, --- 集会匹配
}

local ConstantsCatHouse = CatHouseMgr.ConstantsCatHouse



local CatHouseListBtnNodeEnvPath = "Game.CatHouse.CatHouseListBtnNode"
------------ define ------------

function CatHouseMatchPopupMyCat:__init()
    self.frame = nil
end

function CatHouseMatchPopupMyCat:__delete()
    self.frame = nil
end

function CatHouseMatchPopupMyCat:Awake()
    self.frame = self.BtnBefore.transform:Find("ImgFrame")
    SetButtonAction(self.BtnClose, Bind(self, self.OnClickBtnCloseAction))
    SetButtonAction(self.BtnBefore, Bind(self, self.OnClickBtnBeforeAction))

    --- 训练次数上限（同时也是进化所需数量）
    self.trainTimeLimit = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.TrainTimeLimit).num)
end

function CatHouseMatchPopupMyCat:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


