function CatHouseMatchPopupMyCat:FreshUI(myCatData, matchType)
    local isShowCat = myCatData ~= nil
    --KTool.SetActive(self.BeforeChoose.gameObject, not isShowCat)
    self.TextTitle.text = isShowCat and localize("我的猫咪") or localize("可选择")
    KTool.SetActive(self.AfterChoose.gameObject, isShowCat)
    if isShowCat then
        CfUtils.SetUISwitchImage(self.frame, 2)
    else
        CfUtils.SetUISwitchImage(self.frame, 1)
    end

    if isShowCat then
        self:FreshCatNode(self.CatHouseListBtnNode, myCatData)
        KTool.SetActive(self.BtnClose.gameObject, matchType ~= MatchType.FriendMatchComplete)
    end

end

function CatHouseMatchPopupMyCat:FreshCatNode(node, catData)
    ---@type CatHouseListBtnNode
    local env = CfUtils.GetLuaScr(node, CatHouseListBtnNodeEnvPath)
    if isNull(env) then return end
    env:FreshCommonUI(catData)
    env:FreshTimes(self.trainTimeLimit)
    -- env:FreshSignupUI()
end
